import { expect, test } from 'vitest';

import { toRedirectsFile } from '#generate-redirects/redirects-file.ts';

test('writes each exact rule with and without its slash, and every dynamic rule last', () => {
	const file = toRedirectsFile(
		[
			['/lists/*', '/:splat'],
			['/', '/home/'],
			['/sitemap.xml', '/sitemap-index.xml'],
			['/:slug/feed/', '/rss.xml'],
			['/about/booking/', '/booking/'],
		],
		[{ from: '/old-post/', to: '/a-post/' }],
	);

	expect(file.split('\n')).toEqual([
		'# Generated by `pnpm build`; do not edit',
		'',
		'# Structural moves off WordPress, hand-written in generate-redirects/index.ts',
		'/ /home/ 301',
		'/sitemap.xml /sitemap-index.xml 301',
		'/about/booking/ /booking/ 301',
		'/about/booking /booking/ 301',
		'',
		'# Generated from `formerIds`',
		'/old-post/ /a-post/ 301',
		'/old-post /a-post/ 301',
		'',
		'# Dynamic rules last: Cloudflare counts every rule below one as dynamic, and allows 100',
		'/lists/* /:splat 301',
		'/:slug/feed/ /rss.xml 301',
		'',
	]);
});
